import datetime
from odoo import fields, models, api, _
from odoo.exceptions import ValidationError
import requests
import json
import logging
from datetime import date
import random

_logger = logging.getLogger(__name__)


class FoodicConnector(models.Model):
    _name = "foodic.connector"
    _description = "Foodics Connector"

    @api.depends("mode")
    def get_base_url(self):
        """
        get the base url
        :return:
        """
        for rec in self:
            url = 'https://'
            access_url = 'https://'
            if rec.mode == 'production':
                url += "api.foodics.com/v5"
                access_url += "api.foodics.com/oauth/token"
            else:
                url += "api-sandbox.foodics.com/v5"
                access_url += "api-sandbox.foodics.com/oauth/token"
            rec.base_url = url
            rec.access_url = access_url

