    name = fields.Char("Name")
    mode = fields.Selection(
        [('sandbox', 'Sandbox'), ('production', 'Production')], default='sandbox')
    base_url = fields.Char("Base Url", compute=get_base_url)
    access_url = fields.Char('Access Url', compute=get_base_url)
    code = fields.Char('Code')
    redirect_uri = fields.Char('Redirect Uri')
    access_token = fields.Text("Access Token")
    state = fields.Selection(
        [('draft', 'Draft'), ('authenticated', 'Authenticated')], default="draft")
    is_automatically_sync = fields.Boolean("Is Automatically Sync?")
    description = fields.Html("Description", default=get_description)
    foodics_state_code = fields.Char("Foodics State")
    every_hours = fields.Float("Every Hours")
    last_update = fields.Datetime("Last Update")

    @api.model_create_multi
    def create(self, vals_list):
        random_num = random.randint(1000, 90000)
        res = super(FoodicConnector, self).create(vals_list)
        res.foodics_state_code = random_num
        return res

    def get_status_code_message(self, status_code):
        """
        to get Error Message
        :param status_code:
        :return:
        """
        error_message = {
            200: "200 : Successful API call.",
            401: "401 : No valid Access Token was given.",
            403: "403 : You do not have permission to access this resource.",
            404: "404 : The requested resource could not be found.",
            422: "422 : The payload has missing required parameters or invalid data was given.",
            429: "429 : Too many attempts.",
            500: "500 : Request failed due to an internal error in Foodics.",
            503: "503 : Foodics is offline for maintenance."
        }
        if error_message.get(status_code):
            return error_message.get(status_code)
        return "Other : Somthing went wrong."

    def generate_code(self):
        """
                Generates an access token using the provided authorization code and other parameters.
        """
        url = f"https://console-sandbox.foodics.com/authorize?client_id={self.env['ir.config_parameter'].sudo().get_param('entrivis_pos_auto_close_session.client_id')}&state={self.foodics_state_code}"
        return {
            'type': 'ir.actions.act_url',
            'url': url,
            'target': 'self',
        }

    def generate_access_token(self):
        config_parameter_obj = self.env['ir.config_parameter'].sudo()
        headers = {"Content-Type": "application/json",
            "Accept": "application/json", "Catch-Control": "no-cache"}
        json_data = {'grant_type': 'authorization_code',
                     "code": self.code,
                     "client_id": config_parameter_obj.get_param('entrivis_pos_auto_close_session.client_id'),
                     "client_secret": config_parameter_obj.get_param('entrivis_pos_auto_close_session.client_secret'),
                     "redirect_uri": 'https://fodex-demo.odoo.com'
                     }
        response = requests.post(
            self.access_url, data=json.dumps(json_data), headers=headers)
        if response.json().get('access_token'):
            self.state = 'authenticated'
        _logger.info('---------------- response : %s' % (response.json()))
        self.access_token = response.json().get(
            'access_token') or response.json().get('error')

    @api.onchange("is_automatically_sync")
    def onchange_automatically_sync(self):
        cron_id = self.env.ref("entrivis_foodics_base.ir_cron_sync_data", raise_if_not_found=False)
        if cron_id:
            cron_id.active = bool(self.is_automatically_sync)

    def reset_to_draft(self):
        """
        Confirm Connection
        :return:
        """
        self.state = 'draft'

    def get_header(self):
        """
        headers={'Content-Type': 'application/json'}
        :return:
        """
        headers = {'Content-Type': 'application/json',
            'Accept': 'application/json'}
        if self.access_token:
            token = "Bearer " + self.access_token
            headers.update({'Authorization': token})
        return headers

    def sync_all_data(self):
        """
            This method is responsible for triggering synchronization of various data types.

            It searches for an authenticated 'foodic.connector' and checks if automatic syncing is enabled.
            If both conditions are met, it calls methods to synchronize users, products, POS taxes,
            payment methods, and tags using the connector.
            """
        connector = self.env['foodic.connector'].search(
            [('state', '=', 'authenticated')], limit=1)
        difference = datetime.datetime.now() - connector.last_update
        if connector and connector.is_automatically_sync:
            hours_interval = datetime.timedelta(hours=connector.every_hours)
            if hours_interval <= difference:
                connector.last_update = datetime.datetime.now()
                connector.sync_tags()
                connector.sync_users()
                connector.sync_branch()
                connector.sync_customers()
                connector.sync_products()
                connector.sync_modifiers()
                connector.sync_payment_methods()
                connector.sync_tax_groups()
                connector.sync_pos_taxes()
                connector.sync_pos_charges()

    def create_foodics_history_record(self, request_url, value, response):
        """
        create a data for foodics history
        :param value:
        :param response:
        :param model: Model object
        :param request_url: Request URL
        :param payload: Payload used in the API request
        :param vals: Dictionary containing data for the response
        :return:
        """
        history_data = {
            'date_time': datetime.datetime.now(),
            'user_id': self.create_uid.id,
            'req_url': request_url,
            'req_data': value,
            'response': response,
        }
        self.env['foodics.history'].create(history_data)

    def show_notification(self, message, type):
        title = ''
        if type == 'danger':
            title = "Error"
        if type == 'success':
            title = "Success"
        return {
            'type': 'ir.actions.client',
            'tag': 'display_notification',
            'params': {
                'title': _(title),
                'type': type,
                'message': _(message)
            }
        }

    def call_foodics_api(self, method="GET", post_url='/', payload={}):
        """
        Read Product Data and return Data
        :return:
        """
        try:
            headers = self.get_header()
            url = self.base_url + post_url
            response_text = requests.request(
                method, url, headers=headers, data=payload)
            if response_text.status_code == 200:
                response = json.loads(response_text.text)
                self.create_foodics_history_record(
                    url, payload, response_text.text)
                return response
            else:
                massage = self.get_status_code_message(
                    response_text.status_code)
                _logger.error(
                    'Foodics Integration Issue, Status Code : %s' % response_text.status_code)
                self.create_foodics_history_record(url, payload, massage)
                return {
                    'error': True,
                    'error_message': massage
                }
        except Exception as e:
            _logger.error(e)
            self.create_foodics_history_record(url, payload, e)
            return {
                'error': True,
                'error_message': e
            }

    def sync_products(self):
        """
        :return:
        """
        read_all_products = self.call_foodics_api('GET', '/products', {})
        if 'error' and 'error_message' in read_all_products:
            return self.show_notification(read_all_products['error_message'], 'danger')
        for product_data in read_all_products.get('data', []):
            foodics_id = product_data.get('id') or ''
            if foodics_id:
                product_rec = self.env['product.product'].search(
                    [('foodics_id', '=', foodics_id)])
                vals = product_rec.prepare_data_foodics_to_odoo(product_data)
                if 'error' and 'error_message' in vals:
                    return self.show_notification(vals['error_message'], 'danger')
                if product_rec:
                    product_rec.update(vals)
                else:
                    product_rec.create(vals)
        return self.show_notification('Product Sync Successfully', 'success')

