    def prepare_charges_data(self, data):
        vals = {
            'foodics_id': data.get('id'),
            'name': data.get('name', ''),
            'list_price': int(data.get('value', 1)),
            'standard_price': int(data.get('value', 1)),
            'detailed_type': 'service',
            'is_sync_with_foodics': True
        }
        tax_ids = data.get('tax_group', [])
        tax_id = []
        if tax_ids:
            for tax in tax_ids:
                tax_rec = self.env['account.tax'].search([('foodics_id', '=', tax)])
                if tax_rec:
                    tax_id.append(tax_rec.id)
        vals['taxes_id'] = [(6, 0, tax_id)]
        return vals

    def sync_tags(self):
        """
        Num  |  Tag Type
        7    |  Product Tag
        1    | Customer Tag
        5    | Supplier Tag
        :return:
        """
        read_all_tags = self.call_foodics_api('GET', '/tags?filter[type]=7,5,1', {})
        if 'error' and 'error_message' in read_all_tags:
            return self.show_notification(read_all_tags['error_message'], 'danger')
        for tag_data in read_all_tags.get('data', []):
            foodics_id = tag_data.get('id') or ''
            foodics_tag_type = tag_data.get('type') or ''
            if foodics_id and foodics_tag_type == 7:
                tag_rec = self.env['product.tag'].search([('foodics_id', '=', foodics_id)])
                tag_vals = tag_rec.prepare_tag_data(tag_data)
                if tag_rec:
                    tag_rec.update(tag_vals)
                else:
                    tag_rec.create(tag_vals)
            elif foodics_id and (foodics_tag_type == 1 or foodics_tag_type == 5):
                cus_tag_rec = self.env['res.partner.category'].search([('foodics_id', '=', foodics_id)])
                tag_vals = cus_tag_rec.prepare_cus_tag_data(tag_data)
                if cus_tag_rec:
                    cus_tag_rec.update(tag_vals)
                else:
                    cus_tag_rec.create(tag_vals)
        return self.show_notification('Tags Sync Successfully', 'success')

    def sync_users(self):
        """Read User Data from Foodics"""
        """Dummy User Data For Testing"""
        read_all_users = self.call_foodics_api('GET', '/users', {})
        if 'error' and 'error_message' in read_all_users:
            return self.show_notification(read_all_users['error_message'], 'danger')
        user_name_list = ''
        for user_data in read_all_users.get('data', []):
            foodics_id = user_data.get('id') or ''
            user_rec = self.env['res.users'].search([('foodics_id', '=', foodics_id)])
            if user_data.get('email'):
                user_vals = user_rec.prepare_user_data(user_data)
                if user_rec:
                    user_rec.update(user_vals)
                else:
                    user_rec.create(user_vals)
            else:
                user_name_list += user_data.get('name') + ', '
        if user_name_list:
            return self.show_notification(
                "Some of user are not sync because login (email) field is missing." +
                user_name_list[0:-2], 'danger')
        else:
            return self.show_notification('Users Sync Successfully', 'success')

    def sync_payment_methods(self):
        """
        Sync Payment Methods
        #  | Type
        1 |	Cash
        2 |	Card
        :return:
        """
        read_all_payment_methods = self.call_foodics_api('GET', '/payment_methods?filter[type]=1,2', {})
        if 'error' and 'error_message' in read_all_payment_methods:
            return self.show_notification(read_all_payment_methods['error_message'], 'danger')
        for payment_method in read_all_payment_methods.get('data', []):
            foodics_id = payment_method.get('id') or ''
            if foodics_id:
                payment_method_rec = self.env['pos.payment.method'].search([('foodics_id', '=', foodics_id)])
                vals = payment_method_rec.prepare_payment_method_data(payment_method)
                if payment_method_rec:
                    payment_method_rec.update(vals)
                else:
                    payment_method_rec.create(vals)
        return self.show_notification('Payment Method Sync Successfully', 'success')

    def sync_branch(self):
        """
        Sync Branch
        :return:
        """
        read_all_branch = self.call_foodics_api('GET', '/branches', {})
        if 'error' and 'error_message' in read_all_branch:
            return self.show_notification(read_all_branch['error_message'], 'danger')
        for each_branch in read_all_branch.get('data', []):
            foodics_id = each_branch.get('id') or ''
            if foodics_id:
                branch_rec = self.env['pos.config'].search([('foodics_id', '=', foodics_id)])
                vals = branch_rec.prepare_branch_data(each_branch)
                if branch_rec:
                    branch_rec.update(vals)
                else:
                    branch_rec.create(vals)
        return self.show_notification('Branch Sync Successfully', 'success')

    def sync_tax_groups(self):
        """
        :return:
        """
        post_url = '/tax_groups'
        sync_all_tax_group = self.call_foodics_api('GET', post_url, {})
        if 'error' and 'error_message' in sync_all_tax_group:
            return self.show_notification(sync_all_tax_group['error_message'], 'danger')
        for rec in sync_all_tax_group.get('data', []):
            foodics_id = rec.get('id') or ''
            tax_groups_id = self.env['account.tax.group'].search([('foodics_id', '=', foodics_id)])
            tag_vals = tax_groups_id.prepare_tax_group_data(rec)
            if tax_groups_id:
                tax_groups_id.update(tag_vals)
            else:
                tax_groups_id.create(tag_vals)
        return self.show_notification('Tax Groups Successfully', 'success')
